class Solution {
public:
    long long taskSchedulerII(vector<int>& tasks, int space) {
        unordered_map<int, long long> lastDone;
        long long day = 0;
        for (int t : tasks) {
            day++;
            auto it = lastDone.find(t);
            if (it != lastDone.end() && day - it->second <= space) {
                day = it->second + space + 1;
            }
            lastDone[t] = day;
        }
        return day;
    }
};
